<script lang="ts">
import {onMount} from 'svelte';import {db,seed,rupiah,type Product,type Sale,type Job,type Service} from './lib/database';import {LayoutDashboard,ShoppingCart,Package,Printer,ClipboardList,Truck,ChartNoAxesCombined,Settings,Search,Plus,Trash2,Check,LogOut,Menu,FileText,Boxes,Users} from 'lucide-svelte';
let page='Overview',ready=false,role='',user='',notice='',products:Product[]=[],sales:Sale[]=[],jobs:Job[]=[],services:Service[]=[],suppliers:any[]=[],purchases:any[]=[],query='',category='Semua kategori',cart:{p:Product,q:number}[]=[],showProduct=false,showJob=false,showPurchase=false,edit:Product|null=null;let form:any={sku:'',name:'',category:'Alat Tulis',brand:'',unit:'PCS',cost:0,price:0,stock:0,minimum:3,barcode:''};let job:any={service:'',customer:'Pelanggan Umum',pages:1,copies:1,size:'A4',color:'B/W',duplex:false,note:'',file:null};let buy:any={supplier:'',product:'',qty:1};let discount=0;
const nav=[['Overview',LayoutDashboard],['Kasir / POS',ShoppingCart],['Produk ATK',Package],['Antrean Pekerjaan',ClipboardList],['Pembelian',Truck],['Riwayat Transaksi',FileText],['Laporan',ChartNoAxesCombined],['Pengaturan',Settings]] as const;
const rolePages:Record<string,string[]>={owner:nav.map(([label])=>label),cashier:['Overview','Kasir / POS','Produk ATK','Antrean Pekerjaan','Riwayat Transaksi'],operator:['Overview','Antrean Pekerjaan']};
$: allowedPages=rolePages[role]||[];
$: visibleNav=nav.filter(([label])=>allowedPages.includes(label));
$: if(ready&&role&&allowedPages.length&&!allowedPages.includes(page))page=role==='cashier'?'Kasir / POS':role==='operator'?'Antrean Pekerjaan':'Overview';
$: filtered=products.filter(p=>p.active&&(category==='Semua kategori'||p.category===category)&&`${p.name} ${p.sku} ${p.barcode} ${p.brand}`.toLowerCase().includes(query.toLowerCase()));$:subtotal=cart.reduce((n,x)=>n+x.p.price*x.q,0);$:total=Math.max(0,subtotal-Number(discount||0));$: todaySales=sales.filter(s=>new Date(s.date).toDateString()===new Date().toDateString());$: todayRevenue=todaySales.reduce((n,s)=>n+s.total,0);$: waiting=jobs.filter(j=>j.status==='WAITING').length;
async function refresh(){products=await db.products.toArray();sales=(await db.sales.toArray()).sort((a,b)=>b.date.localeCompare(a.date));jobs=(await db.jobs.toArray()).sort((a,b)=>a.date.localeCompare(b.date));services=await db.services.toArray();suppliers=await db.suppliers.toArray();purchases=await db.purchases.toArray()}
onMount(async()=>{try{await seed();await refresh();role=localStorage.getItem('copypos-role')||'';user=role;page=role==='cashier'?'Kasir / POS':role==='operator'?'Antrean Pekerjaan':'Overview';ready=true}catch{notice='Database lokal gagal dibuka'}});function toast(t:string){notice=t;setTimeout(()=>notice='',2800)}function login(r:string){role=r;user=r;page=r==='cashier'?'Kasir / POS':r==='operator'?'Antrean Pekerjaan':'Overview';localStorage.setItem('copypos-role',r)}function logout(){role='';user='';page='Overview';localStorage.removeItem('copypos-role')}
function newProduct(){edit=null;form={sku:'',name:'',category:'Alat Tulis',brand:'',unit:'PCS',cost:0,price:0,stock:0,minimum:3,barcode:''};showProduct=true}function editProduct(p:Product){edit=p;form={...p};showProduct=true}
async function saveProduct(){if(!form.sku.trim()||!form.name.trim())return toast('SKU dan nama produk wajib diisi');const duplicate=await db.products.where('sku').equals(form.sku.trim()).first();if(duplicate&&duplicate.id!==edit?.id)return toast('SKU sudah digunakan');await db.products.put({...form,id:edit?.id||crypto.randomUUID(),sku:form.sku.trim(),name:form.name.trim(),price:+form.price,cost:+form.cost,stock:+form.stock,minimum:+form.minimum,active:true,createdAt:edit?.createdAt||new Date().toISOString()});showProduct=false;await refresh();toast('Produk tersimpan')}
async function removeProduct(p:Product){if(!confirm(`Hapus ${p.name}? Produk dengan histori akan dinonaktifkan.`))return;const used=sales.some(s=>s.items.some(i=>i.productId===p.id));if(used)await db.products.update(p.id,{active:false});else await db.products.delete(p.id);await refresh();toast(used?'Produk dinonaktifkan':'Produk dihapus')}
function add(p:Product){if(p.stock<1)return toast('Stok habis');const row=cart.find(x=>x.p.id===p.id);if(row){if(row.q>=p.stock)return toast('Jumlah melampaui stok');row.q++;cart=[...cart]}else cart=[...cart,{p,q:1}]}
async function checkout(){if(!cart.length)return;const date=new Date().toISOString(),saleId=crypto.randomUUID(),number=`CP-${date.slice(0,10).replaceAll('-','')}-${String(Date.now()).slice(-4)}`,sale:Sale={id:saleId,number,date,customer:'Pelanggan Umum',subtotal,discount:+discount,total,paid:total,payment:'Tunai',items:cart.map(x=>({productId:x.p.id,name:x.p.name,sku:x.p.sku,qty:x.q,unit:x.p.unit,price:x.p.price,cost:x.p.cost})),status:'COMPLETED',cashier:user};try{await db.transaction('rw',[db.products,db.sales,db.movements],async()=>{for(const x of cart){const p=await db.products.get(x.p.id);if(!p||p.stock<x.q)throw Error('Stok berubah atau tidak cukup');await db.products.update(p.id,{stock:p.stock-x.q});await db.movements.add({id:crypto.randomUUID(),productId:p.id,type:'SALE_OUT',quantity:x.q,before:p.stock,after:p.stock-x.q,date,reference:number})}await db.sales.add(sale)});cart=[];discount=0;await refresh();toast(`Transaksi ${number} tersimpan`)}catch(e){toast((e as Error).message)}}
function openJob(){job={service:services.find(s=>s.category==='Fotokopi')?.name||services[0]?.name,customer:'Pelanggan Umum',pages:1,copies:1,size:'A4',color:'B/W',duplex:false,note:'',file:null};showJob=true}
$: selectedService=services.find(s=>s.name===job.service);
$: jobPaper=selectedService&&(selectedService.category==='Print'||selectedService.category==='Fotokopi')?(job.duplex?Math.ceil(+job.pages/2):+job.pages)*+job.copies:0;
$: jobPrice=selectedService?selectedService.price*(selectedService.mode==='PER_PAGE'?+job.pages*+job.copies:+job.copies):0;
async function saveJob(){if(!job.service||+job.pages<1||+job.copies<1)return toast('Lengkapi layanan, halaman dan jumlah');const date=new Date().toISOString(),num=`CP-${date.slice(0,10).replaceAll('-','')}-${String(Date.now()).slice(-4)}`,file=job.file as File|null;await db.jobs.add({id:crypto.randomUUID(),number:num,date,customer:job.customer||'Pelanggan Umum',service:job.service,pages:+job.pages,copies:+job.copies,size:job.size,color:job.color,duplex:!!job.duplex,paper:jobPaper,price:jobPrice,status:'WAITING',note:job.note,operator:'',fileName:file?.name,file:file||undefined});showJob=false;await refresh();toast(`Order ${num} masuk antrean`)}
async function moveJob(j:Job,status:string){try{await db.transaction('rw',[db.jobs,db.products,db.movements],async()=>{const current=await db.jobs.get(j.id);if(!current)throw Error('Order tidak ditemukan');if(status==='COMPLETED'&&!current.consumed){const paper=products.find(p=>p.name.toLowerCase().includes(current.size.toLowerCase())&&p.category==='Kertas');if(paper){const p=await db.products.get(paper.id);if(!p||p.stock<current.paper)throw Error(`Stok ${current.size} tidak cukup`);await db.products.update(p.id,{stock:p.stock-current.paper});await db.movements.add({id:crypto.randomUUID(),productId:p.id,type:'SERVICE_USE',quantity:current.paper,before:p.stock,after:p.stock-current.paper,date:new Date().toISOString(),reference:j.number})}}await db.jobs.update(j.id,{status,consumed:status==='COMPLETED'||current.consumed,operator:user==='operator'?'Operator Demo':user})});await refresh();toast('Status pekerjaan diperbarui')}catch(e){toast((e as Error).message)}}
async function savePurchase(){const p=products.find(x=>x.id===buy.product);if(!p||+buy.qty<1||!buy.supplier)return toast('Lengkapi supplier, produk, dan jumlah');const date=new Date().toISOString(),num=`PB-${Date.now().toString().slice(-7)}`;await db.transaction('rw',[db.products,db.purchases,db.movements],async()=>{const fresh=await db.products.get(p.id);if(!fresh)throw Error('Produk tidak ditemukan');await db.products.update(p.id,{stock:fresh.stock+ +buy.qty});await db.purchases.add({id:crypto.randomUUID(),number:num,date,supplier:buy.supplier,total:p.cost*+buy.qty,product:p.name,qty:+buy.qty});await db.movements.add({id:crypto.randomUUID(),productId:p.id,type:'PURCHASE_IN',quantity:+buy.qty,before:fresh.stock,after:fresh.stock+ +buy.qty,date,reference:num})});showPurchase=false;await refresh();toast('Pembelian diterima, stok bertambah')}
function exportCsv(){const csv=['Nomor,Tanggal,Pelanggan,Total',...sales.map(s=>`${s.number},${s.date},${s.customer},${s.total}`)].join('\n');download(csv,'text/csv','copypOS-transaksi.csv')}async function backup(){const payload={products:await db.products.toArray(),sales:await db.sales.toArray(),jobs:await db.jobs.toArray(),services:await db.services.toArray(),movements:await db.movements.toArray()};download(JSON.stringify(payload,null,2),'application/json','copypOS-backup.json')}function download(body:string,type:string,name:string){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([body],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
</script>
{#if !ready}<div class="loading">COPY<span>POS</span><small>Menyiapkan database lokal…</small></div>{:else if !role}<main class="login-screen"><section class="login-card"><div class="brand-mark">CP</div><p class="eyebrow">STATIONERY & PRINT MANAGEMENT</p><h1>Selamat datang di<br/>CopyPOS.</h1><p class="muted">Demo kasir ATK, fotokopi, dan layanan cetak yang berjalan lokal di browser.</p><div class="login-choices"><button class="primary" onclick={()=>login('owner')}>Owner <small>Semua modul · produk, pembelian, tarif & laporan</small></button><button class="secondary" onclick={()=>login('cashier')}>Kasir <small>POS, katalog, dan order pelanggan</small></button><button class="secondary" onclick={()=>login('operator')}>Operator <small>Antrean dan pembaruan status kerja</small></button></div><div class="demo-hint">Akun demo · password <b>demo123</b><br/>Login simulasi, bukan autentikasi produksi.</div></section><aside class="login-aside"><span class="eyebrow">MODE DEMO · DATA LOKAL</span><h2>Layani lebih cepat.<br/>Kelola lebih rapi.</h2><p>Produk ATK, stok kertas, jasa cetak, dan antrean dalam satu alur.</p><div class="aside-stat"><b>{products.length}</b><span>produk demo siap dicoba</span></div></aside></main>{:else}<div class="app-shell"><aside class="sidebar"><div class="logo"><div class="brand-mark">CP</div><div><b>CopyPOS</b><small>STATIONERY & PRINT</small></div></div><div class="demo-chip">{user==='owner'?'PEMILIK':user==='cashier'?'KASIR':'OPERATOR'} · MODE DEMO</div>{#each visibleNav as [label,Icon]}<button class="nav-item" class:active={page===label} onclick={()=>page=label}><Icon size={17}/><span>{label}</span></button>{/each}<div class="sidebar-bottom"><div class="profile"><div class="avatar">{user[0]?.toUpperCase()}</div><div><b>{user==='owner'?'Pemilik':user==='cashier'?'Kasir':'Operator'}</b><small>{user} · sesi demo</small></div><button class="icon-button" aria-label="Keluar" onclick={logout}><LogOut size={15}/></button></div></div></aside><main class="main-area"><header class="topbar"><div><p class="eyebrow">{page==='Overview'?'RINGKASAN TOKO':'COPYPOS / '+page.toUpperCase()}</p><h1>{page==='Overview'?'Selamat datang kembali':page}</h1></div><div class="top-actions"><span class="today">{new Date().toLocaleDateString('id-ID',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</span>{#if role!=='operator'}<button class="secondary" onclick={openJob}><Plus size={15}/> Buat order</button>{/if}</div></header><div class="demo-banner"><span>●</span> MODE DEMO — DATA TERSIMPAN LOKAL DI BROWSER INI {#if role==='owner'}<button onclick={backup}>Backup data</button>{/if}</div><section class="content">
{#if page==='Overview'}<div class="welcome-row"><div><h2>Operasional hari ini</h2><p>Ringkasan langsung dari database lokal CopyPOS.</p></div><button class="primary" onclick={()=>page='Kasir / POS'}><ShoppingCart size={16}/> Buka kasir</button></div><div class="metrics"><article class="metric"><div class="metric-label">Penjualan hari ini</div><strong>{rupiah(todayRevenue)}</strong><small>{todaySales.length} transaksi tercatat</small></article><article class="metric"><div class="metric-label">Order menunggu</div><strong>{waiting}</strong><small>{jobs.filter(j=>j.status==='IN_PROGRESS').length} sedang dikerjakan</small></article><article class="metric"><div class="metric-label">Siap diambil</div><strong>{jobs.filter(j=>j.status==='READY').length}</strong><small>Perlu diserahkan ke pelanggan</small></article><article class="metric"><div class="metric-label">Produk aktif</div><strong>{products.filter(p=>p.active).length}</strong><small>{products.filter(p=>p.stock<=p.minimum).length} stok menipis</small></article></div><div class="dashboard-grid"><section class="panel table-panel"><div class="panel-head"><div><h3>Antrean pekerjaan</h3><p>Status order jasa terbaru</p></div><button class="secondary" onclick={()=>page='Antrean Pekerjaan'}>Lihat semua</button></div><div class="table-wrap"><table><thead><tr><th>ORDER</th><th>PELANGGAN</th><th>LAYANAN</th><th>BIAYA</th><th>STATUS</th></tr></thead><tbody>{#each jobs.slice(0,5) as j}<tr><td><b>{j.number}</b></td><td>{j.customer}</td><td>{j.service}</td><td>{rupiah(j.price)}</td><td><span class="tag neutral">{j.status}</span></td></tr>{/each}</tbody></table></div></section><section class="panel table-panel"><div class="panel-head"><div><h3>Transaksi terbaru</h3><p>Penjualan barang dan jasa</p></div></div>{#if !sales.length}<div class="empty"><b>Belum ada transaksi baru</b><span>Mulai dari POS untuk mencatat penjualan.</span></div>{:else}<div class="table-wrap"><table><tbody>{#each sales.slice(0,5) as s}<tr><td><b>{s.number}</b><small>{new Date(s.date).toLocaleString('id-ID')}</small></td><td>{s.customer}</td><td class="right"><b>{rupiah(s.total)}</b></td></tr>{/each}</tbody></table></div>{/if}</section></div>
{:else if page==='Produk ATK'}<div class="welcome-row"><div><h2>Katalog dan persediaan</h2><p>{filtered.length} produk · perubahan tersimpan langsung ke IndexedDB.</p></div><button class="primary" onclick={newProduct}><Plus size={16}/> Tambah produk</button></div><div class="toolbar"><label class="search-box"><Search size={16}/><input bind:value={query} placeholder="Cari nama, SKU, barcode, merek"/></label><select bind:value={category}><option>Semua kategori</option>{#each [...new Set(products.map(p=>p.category))] as c}<option>{c}</option>{/each}</select></div><section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>PRODUK</th><th>KATEGORI</th><th>MEREK</th><th>STOK</th><th>MODAL</th><th>HARGA JUAL</th><th>STATUS</th><th></th></tr></thead><tbody>{#each filtered as p}<tr><td><b>{p.name}</b><small>{p.sku} · {p.barcode}</small></td><td>{p.category}</td><td>{p.brand}</td><td><b>{p.stock}</b> {p.unit}</td><td>{rupiah(p.cost)}</td><td>{rupiah(p.price)}</td><td><span class="tag" class:good={p.stock>p.minimum} class:warn={p.stock>0&&p.stock<=p.minimum} class:bad={p.stock===0}>{p.stock===0?'Habis':p.stock<=p.minimum?'Menipis':'Tersedia'}</span></td><td><button class="icon-button" onclick={()=>editProduct(p)}>✎</button><button class="icon-button danger-icon" onclick={()=>removeProduct(p)}><Trash2 size={14}/></button></td></tr>{/each}</tbody></table>{#if !filtered.length}<div class="empty"><b>Produk tidak ditemukan</b><span>Ubah kata kunci atau tambahkan produk.</span></div>{/if}</div></section>
{:else if page==='Kasir / POS'}<div class="welcome-row"><div><h2>Kasir ATK</h2><p>Pilih barang untuk menambahkan ke keranjang transaksi.</p></div><button class="secondary" onclick={openJob}><Printer size={15}/> Buat order jasa</button></div><div class="pos-layout"><div><div class="toolbar"><label class="search-box"><Search size={16}/><input bind:value={query} placeholder="Cari produk ATK"/></label></div><div class="product-grid">{#each filtered as p}<button class="pos-product" onclick={()=>add(p)}><div class="pos-product-top"><span class="product-avatar">{p.name[0]}</span><span class="available" class:low={p.stock<=p.minimum}>Stok {p.stock}</span></div><b>{p.name}</b><small>{p.sku} · {p.unit}</small><strong>{rupiah(p.price)}</strong></button>{/each}</div></div><aside class="cart-panel"><div class="cart-head"><b>Keranjang</b><span>{cart.reduce((n,x)=>n+x.q,0)} item</span></div><div class="cart-items">{#each cart as x}<div class="cart-item"><div class="cart-desc"><b>{x.p.name}</b><small>{rupiah(x.p.price)} × {x.q}</small><div class="qty-control"><button onclick={()=>{if(x.q>1)x.q--;else cart=cart.filter(y=>y!==x);cart=[...cart]}}>−</button><b>{x.q}</b><button onclick={()=>add(x.p)}>+</button></div></div><strong>{rupiah(x.p.price*x.q)}</strong></div>{/each}{#if !cart.length}<div class="cart-empty"><ShoppingCart/><b>Keranjang kosong</b><span>Pilih produk dari katalog</span></div>{/if}</div><div class="cart-summary"><div><span>Subtotal</span><b>{rupiah(subtotal)}</b></div><label class="discount-row">Diskon nominal<input type="number" min="0" max={subtotal} bind:value={discount}/></label><div class="total-row"><span>Total</span><strong>{rupiah(total)}</strong></div><button class="checkout-button" disabled={!cart.length} onclick={checkout}>Selesaikan transaksi</button><small class="secure-note">Pembayaran simulasi · tunai</small></div></aside></div>
{:else if page==='Antrean Pekerjaan'}<div class="welcome-row"><div><h2>Antrean print & fotokopi</h2><p>Stok kertas berkurang saat operator mengonfirmasi pekerjaan selesai.</p></div><button class="primary" onclick={openJob}><Plus size={16}/> Buat order</button></div><div class="metrics"><article class="metric"><div class="metric-label">Menunggu</div><strong>{jobs.filter(j=>j.status==='WAITING').length}</strong></article><article class="metric"><div class="metric-label">Dikerjakan</div><strong>{jobs.filter(j=>j.status==='IN_PROGRESS').length}</strong></article><article class="metric"><div class="metric-label">Siap diambil</div><strong>{jobs.filter(j=>j.status==='READY').length}</strong></article><article class="metric"><div class="metric-label">Selesai</div><strong>{jobs.filter(j=>j.status==='COMPLETED').length}</strong></article></div><section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>NO. ORDER</th><th>PELANGGAN / FILE</th><th>LAYANAN</th><th>HALAMAN × COPY</th><th>KERTAS</th><th>TOTAL</th><th>STATUS</th><th>AKSI</th></tr></thead><tbody>{#each jobs as j}<tr><td><b>{j.number}</b><small>{new Date(j.date).toLocaleString('id-ID')}</small></td><td>{j.customer}<small>{j.fileName||j.note||'Tanpa dokumen digital'}</small></td><td>{j.service} · {j.size} · {j.duplex?'Duplex':'Simplex'}</td><td>{j.pages} × {j.copies}</td><td>{j.paper} lembar</td><td>{rupiah(j.price)}</td><td><span class="tag neutral">{j.status}</span></td><td><select aria-label="Status order" value={j.status} onchange={(e)=>moveJob(j,e.currentTarget.value)}><option value="WAITING">Menunggu</option><option value="IN_PROGRESS">Dikerjakan</option><option value="READY">Siap diambil</option><option value="COMPLETED">Selesai</option><option value="CANCELLED">Dibatalkan</option></select></td></tr>{/each}</tbody></table></div></section><p class="privacy-note">File disimpan lokal di browser ini. Tidak dikirim ke server atau disinkronkan antarperangkat. Buka dialog cetak hanya untuk preview/cetak manual.</p>
{:else if page==='Pembelian'}<div class="welcome-row"><div><h2>Penerimaan supplier</h2><p>Barang masuk memperbarui stok dan tercatat pada inventory movement.</p></div><button class="primary" onclick={()=>{buy={supplier:suppliers[0]?.name||'',product:products[0]?.id||'',qty:1};showPurchase=true}}><Plus size={16}/> Catat pembelian</button></div><section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>NO. PEMBELIAN</th><th>TANGGAL</th><th>SUPPLIER</th><th>PRODUK</th><th>QTY</th><th>TOTAL</th></tr></thead><tbody>{#each purchases as p}<tr><td><b>{p.number}</b></td><td>{new Date(p.date).toLocaleDateString('id-ID')}</td><td>{p.supplier}</td><td>{p.product}</td><td>{p.qty}</td><td>{rupiah(p.total)}</td></tr>{/each}</tbody></table>{#if !purchases.length}<div class="empty">Belum ada pembelian tercatat.</div>{/if}</div></section>
{:else if page==='Riwayat Transaksi'}<section class="panel table-panel"><div class="panel-head"><div><h3>Riwayat transaksi</h3><p>{sales.length} transaksi tersimpan · data lokal</p></div></div><div class="table-wrap"><table><thead><tr><th>NOMOR</th><th>TANGGAL</th><th>KASIR</th><th>ITEM</th><th>TOTAL</th><th>PEMBAYARAN</th></tr></thead><tbody>{#each sales as s}<tr><td><b>{s.number}</b></td><td>{new Date(s.date).toLocaleString('id-ID')}</td><td>{s.cashier}</td><td>{s.items.map(i=>`${i.name} × ${i.qty}`).join(', ')}</td><td><b>{rupiah(s.total)}</b></td><td>Lunas · Tunai</td></tr>{/each}</tbody></table>{#if !sales.length}<div class="empty">Belum ada transaksi.</div>{/if}</div></section>
{:else if page==='Laporan'}<div class="welcome-row"><div><h2>Laporan operasional</h2><p>Angka berasal dari transaksi dan pekerjaan pada database lokal.</p></div><button class="secondary" onclick={exportCsv}>Ekspor transaksi CSV</button></div><div class="metrics"><article class="metric"><div class="metric-label">Omzet barang</div><strong>{rupiah(sales.reduce((n,s)=>n+s.total,0))}</strong></article><article class="metric"><div class="metric-label">Order jasa</div><strong>{jobs.length}</strong><small>{rupiah(jobs.reduce((n,j)=>n+j.price,0))} estimasi nilai order</small></article><article class="metric"><div class="metric-label">Stok kertas A4</div><strong>{products.find(p=>p.name.includes('A4 80'))?.stock||0}</strong><small>lembar</small></article><article class="metric"><div class="metric-label">Stok menipis</div><strong>{products.filter(p=>p.stock<=p.minimum).length}</strong></article></div><section class="panel table-panel"><div class="panel-head"><div><h3>Layanan paling sering dipesan</h3><p>Jumlah order tersimpan</p></div></div><div class="table-wrap"><table><tbody>{#each services.map(s=>({s,n:jobs.filter(j=>j.service===s.name).length})).sort((a,b)=>b.n-a.n).slice(0,8) as row}<tr><td><b>{row.s.name}</b></td><td>{row.s.category}</td><td>{row.n} order</td></tr>{/each}</tbody></table></div></section>
{:else}<div class="settings-grid"><section class="panel settings-panel"><div class="panel-head"><div><h3>Pengaturan demo</h3><p>Identitas toko dan master tarif jasa.</p></div></div><p class="demo-disclaimer">Data disimpan di browser ini. Login hanya simulasi. Cetak bergantung browser, OS, dan printer. Tidak ada sinkronisasi cloud.</p><button class="secondary" onclick={backup}>Unduh backup JSON</button></section><section class="panel settings-panel"><div class="panel-head"><div><h3>Tarif layanan</h3><p>Atur nominal per satuan, perubahan tersimpan ke IndexedDB.</p></div></div>{#each services as s}<label class="rate-row">{s.name}<span>Rp <input type="number" min="0" value={s.price} onchange={async e=>{await db.services.update(s.id,{price:+e.currentTarget.value});await refresh();toast('Tarif diperbarui')}}/></span></label>{/each}</section></div>{/if}
</section></main></div>{/if}
{#if showProduct}<div class="overlay"><section class="modal"><div class="modal-head"><div><h2>{edit?'Edit produk':'Tambah produk ATK'}</h2><p>Harga disimpan sebagai snapshot pada transaksi.</p></div><button class="icon-button" onclick={()=>showProduct=false}>×</button></div><div class="form-grid"><label>SKU *<input bind:value={form.sku}/></label><label>Barcode<input bind:value={form.barcode}/></label><label class="wide">Nama produk *<input bind:value={form.name}/></label><label>Kategori<select bind:value={form.category}>{#each [...new Set([...products.map(p=>p.category),'Alat Tulis','Kertas','Perlengkapan Kantor','Finishing'])] as c}<option>{c}</option>{/each}</select></label><label>Merek<input bind:value={form.brand}/></label><label>Satuan dasar<select bind:value={form.unit}>{#each ['PCS','UNIT','PACK','BOX','DUS','RIM','LEMBAR','SET','ROLL','BOTOL'] as u}<option>{u}</option>{/each}</select></label><label>Harga modal<input type="number" min="0" bind:value={form.cost}/></label><label>Harga jual<input type="number" min="0" bind:value={form.price}/></label><label>Stok<input type="number" min="0" bind:value={form.stock} disabled={!!edit}/></label><label>Stok minimum<input type="number" min="0" bind:value={form.minimum}/></label></div><div class="modal-actions"><button class="secondary" onclick={()=>showProduct=false}>Batal</button><button class="primary" onclick={saveProduct}><Check size={15}/> Simpan produk</button></div></section></div>{/if}
{#if showJob}<div class="overlay"><section class="modal"><div class="modal-head"><div><h2>Buat order jasa</h2><p>Estimasi kertas dan tarif dihitung dari layanan yang dipilih.</p></div><button class="icon-button" onclick={()=>showJob=false}>×</button></div><div class="form-grid"><label class="wide">Layanan<select bind:value={job.service}>{#each services.filter(s=>s.active) as s}<option value={s.name}>{s.name} · {rupiah(s.price)} / {s.mode==='PER_PAGE'?'halaman':'item'}</option>{/each}</select></label><label>Nama pelanggan<input bind:value={job.customer}/></label><label>Ukuran kertas<select bind:value={job.size}><option>A4</option><option>F4</option><option>A3</option><option>Letter</option><option>Legal</option></select></label><label>Halaman<input type="number" min="1" bind:value={job.pages}/></label><label>Jumlah copy<input type="number" min="1" bind:value={job.copies}/></label><label>Warna<select bind:value={job.color}><option>B/W</option><option>Grayscale</option><option>Full Color</option></select></label><label>Mode sisi<select bind:value={job.duplex}><option value={false}>Simplex</option><option value={true}>Duplex</option></select></label><label class="wide">Upload PDF/JPG/PNG (maks. 8 MB)<input type="file" accept="application/pdf,image/jpeg,image/png" onchange={e=>{const f=e.currentTarget.files?.[0];if(f&&f.size>8*1024*1024){toast('Ukuran file melebihi 8 MB');e.currentTarget.value='';return}job.file=f||null}}/></label><label class="wide">Catatan<input bind:value={job.note}/></label></div><p class="privacy-note">File disimpan lokal pada browser dan perangkat ini. File tidak dikirim ke server atau disinkronkan antarperangkat.</p><div class="job-estimate"><span>Estimasi kertas <b>{jobPaper} lembar</b></span><span>Estimasi biaya <b>{rupiah(jobPrice)}</b></span></div><div class="modal-actions"><button class="secondary" onclick={()=>showJob=false}>Batal</button><button class="primary" onclick={saveJob}><Check size={15}/> Simpan ke antrean</button></div></section></div>{/if}
{#if showPurchase}<div class="overlay"><section class="modal compact-modal"><div class="modal-head"><div><h2>Penerimaan pembelian</h2><p>Stok ditambah setelah barang diterima.</p></div><button class="icon-button" onclick={()=>showPurchase=false}>×</button></div><label>Supplier<select bind:value={buy.supplier}>{#each suppliers as s}<option>{s.name}</option>{/each}</select></label><label>Produk<select bind:value={buy.product}>{#each products.filter(p=>p.active) as p}<option value={p.id}>{p.name}</option>{/each}</select></label><label>Jumlah diterima<input type="number" min="1" bind:value={buy.qty}/></label><p class="purchase-total">Total <b>{rupiah((products.find(p=>p.id===buy.product)?.cost||0)*+buy.qty)}</b></p><div class="modal-actions"><button class="secondary" onclick={()=>showPurchase=false}>Batal</button><button class="primary" onclick={savePurchase}>Simpan & tambah stok</button></div></section></div>{/if}{#if notice}<div class="toast"><Check size={15}/>{notice}</div>{/if}
